// Supplied product artwork, encoded as WebP without cropping. Content-hashed URLs permit immutable caching.
export const PRODUCT_ART_URLS={"signal-bridge": "/assets/products/signal-bridge-242bb326874c.webp", "scalper-pro": "/assets/products/scalper-pro-69ba5fdd6b7a.webp"};
const encoded={"/assets/products/signal-bridge-242bb326874c.webp": "", "/assets/products/scalper-pro-69ba5fdd6b7a.webp": ""};
const decoded=new Map();
export function productArt(path,method){if(!Object.hasOwn(encoded,path))return null;if(!["GET","HEAD"].includes(method))return new Response(null,{status:405,headers:{Allow:"GET, HEAD"}});if(method==="GET"&&!decoded.has(path))decoded.set(path,Uint8Array.from(atob(encoded[path]),c=>c.charCodeAt(0)));return new Response(method==="HEAD"?null:decoded.get(path),{headers:{"content-type":"image/webp","cache-control":"public, max-age=31536000, immutable","x-content-type-options":"nosniff"}});}
